// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

const clientes = $json.body.clientes;
const investimentos = $json.investimentos;

const resultado = clientes.map(cliente => {

  // Encontra os investimentos correspondentes ao perfil do cliente
  const opcoes = investimentos.filter(
    investimento => investimento.perfil === cliente.perfil
  );

  // Cria uma lista com os nomes dos investimentos
  const produtos = opcoes
    .map(investimento => investimento.produto)
    .join(", ");

  // Mensagem personalizada de acordo com o perfil
  let mensagem;

  if (cliente.perfil === "Conservador") {
    mensagem = `Olá, ${cliente.nome}! 👋

Identificamos que seu perfil de investidor é Conservador e que você possui um saldo de ${cliente.saldo}.

Para esse perfil, priorizamos opções com foco em segurança e renda fixa.

Algumas opções encontradas para o seu perfil são: ${produtos}.

Esta é uma simulação educacional baseada nos dados do desafio.`;
  }

  else if (cliente.perfil === "Moderado") {
    mensagem = `Olá, ${cliente.nome}! 👋

Identificamos que seu perfil de investidor é Moderado e que você possui um saldo de ${cliente.saldo}.

Para esse perfil, buscamos opções que combinem segurança e potencial de rentabilidade.

Algumas opções encontradas para o seu perfil são: ${produtos}.

Esta é uma simulação educacional baseada nos dados do desafio.`;
  }

  else if (cliente.perfil === "Arrojado") {
    mensagem = `Olá, ${cliente.nome}! 👋

Identificamos que seu perfil de investidor é Arrojado e que você possui um saldo de ${cliente.saldo}.

Para esse perfil, consideramos opções com maior exposição à renda variável e maior potencial de retorno, acompanhadas de maior risco.

Algumas opções encontradas para o seu perfil são: ${produtos}.

Esta é uma simulação educacional baseada nos dados do desafio.`;
  }

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      saldo: cliente.saldo,
      perfil: cliente.perfil,
      investimentos: opcoes,
      mensagem: mensagem
    }
  };
});

return resultado;

